with FilteredSubscriptions as (select *, round(monthly_fee * 1.1, 2) monthly_fee_scaled from subscriptions where start_date <= '2025-07-03'), agg as (select case when plan in ('premium', 'basic') then 'group_a' else 'other' end plan_group, avg(monthly_fee) avg_monthly_fee from FilteredSubscriptions group by case when plan in ('premium', 'basic') then 'group_a' else 'other' end) select * from agg where avg_monthly_fee >= 170 order by avg_monthly_fee, plan_group limit 3
